from collections import defaultdict, Counter

def dfs(tree, node, parent, count):
    for child in tree[node]:
        if child != parent:
            count[node] += dfs(tree, child, node, count)
    char_count = Counter()
    for child in tree[node]:
        if child != parent:
            char_count.update(count[child])
    odd_count = sum(1 for char, cnt in char_count.items() if cnt % 2 == 1)
    longest_path = 0
    if odd_count <= 1:
        longest_path = sum(char_count.values())
    count[node] += 1  # Include the current node itself
    return longest_path

def main():
    n = int(input())
    tree = defaultdict(list)
    for i in range(2, n + 1):
        p, c = input().split()
        tree[i].append(int(p))
        tree[int(p)].append(i)

    count = [0] * (n + 1)
    result = []
    for i in range(1, n + 1):
        result.append(dfs(tree, i, -1, count))
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
